"use strict";
/**
 * engine-server/pipeline/phase-b/ammo-injector.ts — 弹药注入器
 *
 * V1.3 两轮注入架构：
 *   Round 1: matchAmmo(taskDef) → 行业事实弹药，Phase A 前注入（匹配 taskDef 关键词）
 *   Round 2: matchOrgAmmo(teamStructure) → 组织事实弹药，Phase A 后注入（匹配团队结构属性）
 *
 * 注入策略：约束关键词匹配（行业）+ 结构属性匹配（组织）
 * 注入位置：Round 1 在 Phase A prompt，Round 2 在 Phase B prompt
 *
 * @date 2026-05-14 (初始) / 2026-05-15 (两轮架构)
 */
Object.defineProperty(exports, "__esModule", { value: true });
exports.matchAmmo = matchAmmo;
exports.formatAmmoForPrompt = formatAmmoForPrompt;
