/**
 * 从弹药库匹配与任务约束相关的条目。
 *
 * @param taskDef - 任务定义
 * @param maxEntries - 最大返回条目数（避免 prompt 过长）
 * @returns 匹配到的弹药条目列表
 */
function matchAmmo(taskDef, maxEntries = 5) {
    const queryText = [
        taskDef.job,
        ...taskDef.constraints,
        ...taskDef.successMetrics,
    ]
        .join(' ')
        .toLowerCase();
    if (!queryText.trim())
        return [];
    // 对每条弹药打分
    const scored = [];
    for (const entry of ammo_depot_1.AMMO_DEPOT) {
        let score = 0;
        const keywordText = entry.keywords.join(' ').toLowerCase();
        // 关键词精确匹配
        for (const kw of entry.keywords) {
            if (queryText.includes(kw.toLowerCase())) {
                score += 2;
            }
        }
        // 行业名匹配
        if (queryText.includes(entry.industry.toLowerCase())) {
            score += 3;
        }
        // 子领域匹配
        if (entry.subdomain && queryText.includes(entry.subdomain.toLowerCase())) {
            score += 2;
        }
        // 部分关键词匹配（如"跨境"匹配"跨境电商"）
        for (const kw of entry.keywords) {
            const parts = kw.split(/\s+/);
            for (const part of parts) {
                if (part.length >= 3 && queryText.includes(part.toLowerCase())) {
                    score += 1;
                }
            }
        }
        if (score > 0) {
            scored.push({ entry, score });
        }
    }
    // 按分数降序，取 top-N
    scored.sort((a, b) => b.score - a.score);
    return scored.slice(0, maxEntries).map(s => s.entry);
}
// ================================================================
// 注入格式化
