/**
 * 将匹配到的弹药条目格式化为 prompt 注入文本。
 *
 * @param entries - 匹配到的弹药条目
 * @returns 格式化后的 prompt 注入文本
 */
function formatAmmoForPrompt(entries) {
    if (entries.length === 0)
        return '';
    const lines = [
        '',
        '【领域知识参考】',
        '以下信息来自 ClawOrg 知识库，供你推理时参考：',
        ...entries.map((e, i) => {
            const confidenceLabel = e.confidence === 'verified' ? '✓已验证' :
                e.confidence === 'public_source' ? '📖公开来源' : '🤖LLM生成';
            return `${i + 1}. [${e.industry}${e.subdomain ? '/' + e.subdomain : ''}] ${e.factText} (${confidenceLabel})`;
        }),
        '',
        '请在角色推导时使用以上领域知识，确保角色设计反映真实的行业约束。',
    ];
    return lines.join('\n');
}
