/**
 * 一站式弹药注入：匹配 + 格式化。
 * Round 1 — 行业事实，Phase A 前调用。
 *
 * @param taskDef - 任务定义
 * @returns 弹药注入文本（无匹配时返回空字符串）
 */
function injectAmmo(taskDef) {
    const entries = matchAmmo(taskDef);
    return formatAmmoForPrompt(entries);
}
